UPDATE  JOBON_MEMBER
SET     NICKNAME           = #{nickname, jdbcType=VARCHAR}
       ,INTRODUCTION       = #{introduction, jdbcType=VARCHAR}
       ,INTEREST_JOB       = #{interestJob, jdbcType=VARCHAR}
       ,PREFERRED_LOCATION = #{preferredLocation, jdbcType=VARCHAR}
       ,PROFILE_IMAGE_URL  = NVL(#{profileImageUrl, jdbcType=VARCHAR}, PROFILE_IMAGE_URL)
       ,UPDATED_AT         = SYSTIMESTAMP
WHERE   MEMBER_ID = #{memberId}
